items=(one two three)
export BASH_ARRAY_VALUE="${items[1]}"
python3 - <<'PY'
import hashlib,json,os
from pathlib import Path
b=Path('/workspace/input/source.txt').read_bytes()
p=Path('/workspace/output/tool-proof-1bc5b2ba-0216-4c31-b1c5-3767b9969fdb.json')
p.write_text(json.dumps(dict(nonce='1bc5b2ba-0216-4c31-b1c5-3767b9969fdb',sha256=hashlib.sha256(b).hexdigest(),byteCount=len(b),bashArrayValue=os.environ['BASH_ARRAY_VALUE'],nodeVerified=False,marker='before'),indent=2)+'\n')
PY
node - <<'JS'
const fs = require('fs');
const crypto = require('crypto');
const input = fs.readFileSync('/workspace/input/source.txt');
const path = '/workspace/output/tool-proof-1bc5b2ba-0216-4c31-b1c5-3767b9969fdb.json';
const proof = JSON.parse(fs.readFileSync(path,'utf8'));
if (proof.byteCount !== input.length || proof.sha256 !== crypto.createHash('sha256').update(input).digest('hex')) throw Error('Verification failed');
proof.nodeVerified = true;
fs.writeFileSync(path, JSON.stringify(proof,null,2)+'\n');
console.log(fs.readFileSync(path,'utf8'));
JS
